from solution import is_simple_power
import concurrent.futures
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_is_simple_power(x, n):
    # Obviously correct reference: exists k >= 0 with n**k == x.
    # n**0 == 1 for every n (python semantics), so x == 1 is always True.
    if x == 1:
        return True
    if n == 1:
        return x == 1
    if n == 0:
        return x == 0
    if n == -1:
        return x == -1  # x == 1 already handled above
    # bounded search, enough for the bounded strategies below
    p = 1
    # iterate exponents; stop when magnitude exceeds |x|
    for _ in range(200):
        p = p * n
        if p == x:
            return True
        if abs(p) > abs(x) and abs(n) >= 2:
            # magnitude will only grow from here (for |n|>=2)
            break
        if abs(p) > 10 ** 18:
            break
    return False


def call_with_timeout(x, n, timeout=1.0):
    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
        fut = ex.submit(is_simple_power, x, n)
        return fut.result(timeout=timeout)


# ---- explicit examples from the spec ----

def test_example_1_4_true():
    assert is_simple_power(1, 4) is True


def test_example_2_2_true():
    assert is_simple_power(2, 2) is True


def test_example_8_2_true():
    assert is_simple_power(8, 2) is True


def test_example_3_2_false():
    assert is_simple_power(3, 2) is False


def test_example_3_1_false():
    assert is_simple_power(3, 1) is False


def test_example_5_3_false():
    assert is_simple_power(5, 3) is False


# ---- properties derived from n**k == x with k >= 0 ----

def test_one_is_power_of_any_base():
    # n**0 == 1 for any n
    for n in [-5, -2, -1, 0, 1, 2, 3, 4, 10]:
        assert is_simple_power(1, n) is True


def test_base_one_only_one():
    for x in [-2, -1, 0, 1, 2, 3, 100]:
        assert is_simple_power(x, 1) == (x == 1)


def test_base_minus_one():
    # (-1)**k alternates 1, -1
    assert is_simple_power(1, -1) is True
    assert is_simple_power(-1, -1) is True
    assert is_simple_power(0, -1) is False
    assert is_simple_power(2, -1) is False
    assert is_simple_power(-2, -1) is False


def test_base_zero():
    # 0**0 == 1, 0**k == 0 for k >= 1
    assert call_with_timeout(1, 0) is True
    assert call_with_timeout(0, 0) is True
    # anything else must be False and must terminate
    for x in [2, 3, -1, 5, 100]:
        assert call_with_timeout(x, 0) is False


def test_zero_is_not_power_of_nonzero():
    for n in [-3, -2, -1, 1, 2, 3, 5]:
        assert is_simple_power(0, n) is False


@given(n=st.integers(min_value=2, max_value=5),
       k=st.integers(min_value=0, max_value=8))
def test_true_powers_positive_base(n, k):
    x = n ** k
    assert is_simple_power(x, n) is True


@given(n=st.integers(min_value=-5, max_value=-2),
       k=st.integers(min_value=0, max_value=8))
def test_true_powers_negative_base(n, k):
    x = n ** k
    assert is_simple_power(x, n) is True


@given(n=st.integers(min_value=2, max_value=5),
       k=st.integers(min_value=0, max_value=6),
       d=st.integers(min_value=1, max_value=5))
def test_non_powers_are_false(n, k, d):
    # x strictly between consecutive powers cannot be a power
    lo = n ** k
    hi = n ** (k + 1)
    assume(hi - lo > 1)
    x = lo + d
    assume(lo < x < hi)
    assert is_simple_power(x, n) is False


@given(n=st.integers(min_value=2, max_value=10),
       x=st.integers(min_value=-50, max_value=500))
def test_matches_reference_model(n, x):
    assert is_simple_power(x, n) == ref_is_simple_power(x, n)


@given(n=st.integers(min_value=-10, max_value=10),
       x=st.integers(min_value=-200, max_value=200))
def test_matches_reference_model_incl_negative(n, x):
    assume(n != 0)  # n==0 with x not in (0,1) hangs the buggy impl; tested separately
    assert is_simple_power(x, n) == ref_is_simple_power(x, n)


def test_returns_bool():
    assert isinstance(is_simple_power(8, 2), bool)
    assert isinstance(is_simple_power(3, 2), bool)
